-- Identifier-only preflight. Existing selections and unsupported/custom settings are not overwritten.
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW `axxdep_host_pipeline_migration` AS
SELECT h.oid, h.project_oid, p.deployment_recipe AS legacy_recipe,
    CASE p.deployment_recipe
        WHEN 'LocalBldUsbSelfExtractor' THEN 'axenox/deployer/Pipelines/Deploy/ManualTransfer.php'
        WHEN 'LocalBldUpdaterPull' THEN 'axenox/deployer/Pipelines/Deploy/UpdaterPull.php'
        WHEN 'LocalBldUpdaterCron' THEN 'axenox/deployer/Pipelines/Deploy/UpdaterPolling.php'
        WHEN 'LocalBldUpdaterPush' THEN 'axenox/deployer/Pipelines/Deploy/UpdaterPush.php'
        WHEN 'LocalBldAzureAppServiceManualInstall' THEN 'axenox/deployer/Pipelines/Deploy/AzureManualTransfer.php'
        ELSE NULL
    END AS target_prototype,
    CASE
        WHEN TRIM(COALESCE(h.prototype_file, '')) <> '' THEN 'ALREADY_SELECTED'
        WHEN p.deployment_recipe NOT IN ('LocalBldUsbSelfExtractor', 'LocalBldUpdaterPull',
            'LocalBldUpdaterCron', 'LocalBldUpdaterPush', 'LocalBldAzureAppServiceManualInstall')
            THEN 'MANUAL_REPLACEMENT_REQUIRED'
        WHEN h.configuration IS NULL THEN 'INVALID_DEPLOY_CONFIG'
        WHEN JSON_TYPE(h.configuration) <> 'OBJECT' THEN 'INVALID_DEPLOY_CONFIG'
        WHEN JSON_CONTAINS_PATH(h.configuration, 'all', '$.default_app_config', '$.config') = 1
            THEN 'APP_CONFIG_KEY_CONFLICT'
        WHEN JSON_LENGTH(JSON_REMOVE(h.configuration,
            '$.default_app_config', '$.config', '$.keep_releases', '$.local_vendors', '$.local_packages',
            '$.shared_dirs', '$.copy_dirs', '$.app_service_name', '$.operator_os')) <> 0
            THEN 'UNMAPPED_CONFIG_KEYS'
        WHEN p.deployment_recipe = 'LocalBldAzureAppServiceManualInstall'
            AND (JSON_TYPE(JSON_EXTRACT(h.configuration, '$.app_service_name')) <> 'STRING'
                OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(h.configuration, '$.app_service_name')), '') = '')
            THEN 'AZURE_APP_NAME_REQUIRED'
        WHEN p.deployment_recipe <> 'LocalBldAzureAppServiceManualInstall'
            AND JSON_CONTAINS_PATH(h.configuration, 'one', '$.app_service_name', '$.operator_os') = 1
            THEN 'UNMAPPED_CONFIG_KEYS'
        ELSE 'READY'
    END AS migration_status
FROM (
    SELECT original.*,
        CASE
            WHEN TRIM(COALESCE(original.deploy_config, '')) = '' THEN JSON_OBJECT()
            WHEN JSON_VALID(original.deploy_config) = 1 THEN CAST(original.deploy_config AS JSON)
            ELSE NULL
        END AS configuration
    FROM axxdep_host original
) h
INNER JOIN axxdep_project p ON p.oid = h.project_oid;

-- Contains private configuration; restrict access like the host table.
CREATE TABLE IF NOT EXISTS `axxdep_host_pipeline_migration_backup` (
    host_oid BINARY(16) NOT NULL PRIMARY KEY,
    original_prototype_file VARCHAR(512) NULL,
    original_deploy_config LONGTEXT NULL,
    migrated_prototype_file VARCHAR(512) NOT NULL,
    migrated_deploy_config LONGTEXT NOT NULL
) ENGINE=InnoDB;

INSERT INTO axxdep_host_pipeline_migration_backup (
    host_oid, original_prototype_file, original_deploy_config,
    migrated_prototype_file, migrated_deploy_config
)
SELECT h.oid, h.prototype_file, h.deploy_config, m.target_prototype,
    JSON_SET(
        CASE
            WHEN JSON_CONTAINS_PATH(h.configuration, 'one', '$.default_app_config') = 0 THEN h.configuration
            WHEN JSON_TYPE(JSON_EXTRACT(h.configuration, '$.default_app_config')) = 'NULL'
                THEN JSON_REMOVE(h.configuration, '$.default_app_config')
            ELSE JSON_SET(JSON_REMOVE(h.configuration, '$.default_app_config'), '$.config',
                JSON_EXTRACT(h.configuration, '$.default_app_config'))
        END,
        '$.keep_releases',
        CASE
            WHEN JSON_EXTRACT(h.configuration, '$.keep_releases') IS NULL
                OR JSON_TYPE(JSON_EXTRACT(h.configuration, '$.keep_releases')) = 'NULL'
                THEN CAST('4' AS JSON)
            ELSE JSON_EXTRACT(h.configuration, '$.keep_releases')
        END
    )
FROM (
    SELECT original.*,
        CASE
            WHEN TRIM(COALESCE(original.deploy_config, '')) = '' THEN JSON_OBJECT()
            WHEN JSON_VALID(original.deploy_config) = 1 THEN CAST(original.deploy_config AS JSON)
            ELSE NULL
        END AS configuration
    FROM axxdep_host original
) h
INNER JOIN axxdep_host_pipeline_migration m ON m.oid = h.oid
LEFT JOIN axxdep_host_pipeline_migration_backup backup ON backup.host_oid = h.oid
WHERE m.migration_status = 'READY' AND backup.host_oid IS NULL;

UPDATE axxdep_host h
INNER JOIN axxdep_host_pipeline_migration m ON m.oid = h.oid
INNER JOIN axxdep_host_pipeline_migration_backup backup ON backup.host_oid = h.oid
SET h.prototype_file = backup.migrated_prototype_file,
    h.deploy_config = backup.migrated_deploy_config
WHERE m.migration_status = 'READY'
    AND h.prototype_file <=> backup.original_prototype_file
    AND h.deploy_config <=> backup.original_deploy_config;

-- No installation-root/PHP/connection/relative-path/history data is changed.
SELECT HEX(oid) AS host_uid, HEX(project_oid) AS project_uid, legacy_recipe, migration_status
FROM axxdep_host_pipeline_migration
WHERE migration_status <> 'ALREADY_SELECTED';

-- DOWN

UPDATE axxdep_host h
INNER JOIN axxdep_host_pipeline_migration_backup backup ON backup.host_oid = h.oid
SET h.prototype_file = backup.original_prototype_file,
    h.deploy_config = backup.original_deploy_config
WHERE h.prototype_file = backup.migrated_prototype_file
    AND h.deploy_config <=> backup.migrated_deploy_config;

-- Preserve rollback evidence and subsequent designer edits.
DROP VIEW IF EXISTS axxdep_host_pipeline_migration;
